    public static void main(String[] args) throws Exception {
        String cookie = new String(Files.readAllBytes(Paths.get(args[0]))).trim();
        byte[] raw = Base64.getDecoder().decode(cookie);
        byte[] key = Base64.getDecoder().decode(args[1]);
